async function handle(req) {
  if (req.kind === 'api' && req.path === '/karakterler') {
    const r = await fetch('https://api.sunucum.com/chars?forum=' + req.user.id, {
      headers: { 'X-Api-Key': secrets.UCP_API_KEY },
    });
    return json(await r.json());
  }
}

async function handle(req) {
  if (req.kind === 'page') return;
  if (req.path === '/katil' && req.method === 'POST') {
    if (!req.user) return json({ error: { message: 'Log in first.' } }, 401);
    const anahtar = 'katilim:' + req.user.id;
    if (await kv.get(anahtar)) return json({ error: { message: 'You have already joined.' } }, 409);
    const sira = ((await kv.get('sayac')) ?? 0) + 1;
    await kv.set('sayac', sira);
    await kv.set(anahtar, { ad: String(req.body.ad).slice(0, 40), not: String(req.body.not ?? '').slice(0, 500), sira, zaman: Date.now() });
    return json({ sira });
  }
  return notFound();
}

